    Bug 1971048 - Add subheader to account-hub-header. r=freaktechnik,laurel


    **How to test**
    - Go to accountHubTemplate.inc.xhtml and to the address-book-option-select element, and add an attribute, either subheader-id or subheader-text
    - Subheader-id is for fluent-ids only, subheader-text is for raw text
    - Open address book for account hub to see your subheader text

    tests will be added in a follow up patch

    Differential Revision: https://phabricator.services.mozilla.com/D254292

diff --git a/mail/components/accountcreation/content/widgets/account-hub-header.mjs b/mail/components/accountcreation/content/widgets/account-hub-header.mjs
index 36dd49e6ec5..d39038c3d9c 100644
--- a/mail/components/accountcreation/content/widgets/account-hub-header.mjs
+++ b/mail/components/accountcreation/content/widgets/account-hub-header.mjs
@@ -244,6 +244,10 @@ class AccountHubHeader extends HTMLElement {
   disconnectedCallback() {
     this.#closeButton.removeEventListener("click", this.#closeAccountHub());
   }
+
+  showSubheader() {
+    this.shadowRoot.querySelector("#accountHubHeaderSubheader").hidden = false;
+  }
 }

 customElements.define("account-hub-header", AccountHubHeader);
diff --git a/mail/components/accountcreation/content/widgets/account-hub-step.mjs b/mail/components/accountcreation/content/widgets/account-hub-step.mjs
index 91abf4f3ea9..36ee836478e 100644
--- a/mail/components/accountcreation/content/widgets/account-hub-step.mjs
+++ b/mail/components/accountcreation/content/widgets/account-hub-step.mjs
@@ -8,12 +8,13 @@ import "chrome://messenger/content/accountcreation/content/widgets/account-hub-h
  * Account Hub Step Template
  * Template ID: #accountHubStepTemplate (from accountHubStepTemplate.inc.xhtml)
  *
- * @slot header - Content displayed as the header.
- * @slot subheader - Content displayed as the subheader
  * @slot content - Body content for the step.
  * @attribute {string} title-id - ID of the string to use as title for the step.
  * @attribute {string} subheader-id - ID of the string to use as sub title for
  *  the step.
+ * @attribute {string} subheader-text - String to display as the subheader.
+ *  Can only specify either this or subheader-id, if both are present the
+ *  id will take precedence.
  */
 export class AccountHubStep extends HTMLElement {
   /** @type {DOMLocalization} */
@@ -69,6 +70,16 @@ export class AccountHubStep extends HTMLElement {
         this.shadowRoot.querySelector("#subheader"),
         this.getAttribute("subheader-id")
       );
+
+      this.#header.showSubheader();
+      return;
+    }
+
+    if (this.hasAttribute("subheader-text")) {
+      this.shadowRoot.querySelector("#subheader").textContent =
+        this.getAttribute("subheader-text");
+
+      this.#header.showSubheader();
     }
   }

